[package]
name = "stallion-server"
version = "0.0.0"
edition = "2024"
publish = false

[lib]
crate-type = ["cdylib", "rlib"]

[dependencies]
ciborium = "0.2"
serde = { version = "1", features = ["derive"] }
serde_bytes = "0.11"
worker = "0.8.6"
worker-macros = "0.8.6"
yrs = "0.28"
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum FrameKind {
    Subscribe,
    Unsubscribe,
    Sync,
    Awareness,
    Reject,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Frame {
    pub tile_key: String,
    pub kind: FrameKind,
    #[serde(with = "serde_bytes")]
    pub payload: Vec<u8>,
}

pub const BOARD_KEY: &str = "";

impl Frame {
    pub fn new(tile_key: impl Into<String>, kind: FrameKind, payload: Vec<u8>) -> Self {
        Frame {
            tile_key: tile_key.into(),
            kind,
            payload,
        }
    }

    pub fn encode(&self) -> Vec<u8> {
        let mut bytes = Vec::new();
        ciborium::into_writer(self, &mut bytes).expect("writing to a Vec cannot fail");
        bytes
    }

    pub fn decode(bytes: &[u8]) -> Result<Frame, String> {
        ciborium::from_reader(bytes).map_err(|e| format!("invalid frame: {e}"))
    }
}

pub fn parse_tile_key(key: &str) -> Result<(i32, i64, i64), String> {
    let invalid = || format!("tileKey {key:?} must be level:tx:ty");
    let mut parts = key.split(':');
    let (Some(level), Some(tx), Some(ty), None) =
        (parts.next(), parts.next(), parts.next(), parts.next())
    else {
        return Err(invalid());
    };
    let level: i32 = level.parse().map_err(|_| invalid())?;
    let tx: i64 = tx.parse().map_err(|_| invalid())?;
    let ty: i64 = ty.parse().map_err(|_| invalid())?;
    if !crate::object::ZOOM_RANGE.contains(&level) {
        return Err(format!("tileKey {key:?} has a level outside -40..40"));
    }
    if key != format!("{level}:{tx}:{ty}") {
        return Err(invalid());
    }
    Ok((level, tx, ty))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_the_golden_frame_fixture_from_the_client_codec() {
        let hex = include_str!("../../../packages/schema/fixtures/frame.cbor.hex").trim();
        let frame = Frame::new("-3:4:-5", FrameKind::Sync, vec![0, 1, 2]);
        let encoded: String = frame.encode().iter().map(|b| format!("{b:02x}")).collect();
        assert_eq!(encoded, hex);
        assert_eq!(Frame::decode(&frame.encode()), Ok(frame.clone()));
        let tagged = [
            &[0xa3][..],
            &frame.encode()[1..frame.encode().len() - 4],
            &[0xd8, 0x40, 0x43, 0, 1, 2],
        ]
        .concat();
        assert_eq!(Frame::decode(&tagged), Ok(frame));
    }

    #[test]
    fn rejects_unknown_kinds_and_malformed_tile_keys() {
        let mut bytes = Vec::new();
        use ciborium::Value;
        let raw = Value::Map(vec![
            (Value::Text("tileKey".into()), Value::Text(String::new())),
            (Value::Text("kind".into()), Value::Text("Nope".into())),
            (Value::Text("payload".into()), Value::Bytes(vec![])),
        ]);
        ciborium::into_writer(&raw, &mut bytes).unwrap();
        assert!(Frame::decode(&bytes).is_err());
        assert_eq!(parse_tile_key("0:1:-2"), Ok((0, 1, -2)));
        for key in ["", "0:1", "41:0:0", "0:01:0", "t:0:0:0"] {
            assert!(parse_tile_key(key).is_err(), "{key}");
        }
    }
}
use std::cell::Cell;

use worker::{SqlStorage, SqlStorageValue};

use crate::object::Bbox;

pub type TileCoord = (i32, i64, i64);

#[derive(Debug, Clone, PartialEq)]
pub struct TileRecord {
    pub coord: TileCoord,
    pub doc_state: Vec<u8>,
    pub updated_at: u64,
    pub objects: Vec<(String, Bbox)>,
}

pub trait TileStore {
    fn load(&self, coord: TileCoord) -> Result<Option<Vec<u8>>, String>;
    fn save(&self, record: &TileRecord) -> Result<(), String>;
}

pub const MIGRATIONS: &[&[&str]] = &[&[
    "CREATE TABLE tile (
        level INTEGER NOT NULL,
        tx INTEGER NOT NULL,
        ty INTEGER NOT NULL,
        doc_state BLOB NOT NULL,
        updated_at INTEGER NOT NULL,
        PRIMARY KEY (level, tx, ty)
    )",
    "CREATE TABLE object_index (
        level INTEGER NOT NULL,
        tx INTEGER NOT NULL,
        ty INTEGER NOT NULL,
        object_id TEXT NOT NULL,
        bbox TEXT NOT NULL,
        PRIMARY KEY (level, tx, ty, object_id)
    )",
]];

pub fn bbox_json(bbox: &Bbox) -> String {
    format!(
        "[{},{},{},{}]",
        bbox.min_x, bbox.min_y, bbox.max_x, bbox.max_y
    )
}

pub struct SqlTileStore {
    sql: SqlStorage,
    migrated: Cell<bool>,
}

fn coord_bindings((level, tx, ty): TileCoord) -> Vec<SqlStorageValue> {
    vec![level.into(), tx.into(), ty.into()]
}

impl SqlTileStore {
    pub fn new(sql: SqlStorage) -> Self {
        SqlTileStore {
            sql,
            migrated: Cell::new(false),
        }
    }

    fn run(&self, query: &str, bindings: Vec<SqlStorageValue>) -> Result<(), String> {
        let cursor = self.sql.exec(query, bindings).map_err(|e| e.to_string())?;
        for row in cursor.raw() {
            row.map_err(|e| e.to_string())?;
        }
        Ok(())
    }

    fn migrate(&self) -> Result<(), String> {
        if self.migrated.get() {
            return Ok(());
        }
        self.run(
            "CREATE TABLE IF NOT EXISTS schema_migration (version INTEGER PRIMARY KEY)",
            vec![],
        )?;
        let current = self
            .sql
            .exec(
                "SELECT COALESCE(MAX(version), 0) FROM schema_migration",
                None,
            )
            .map_err(|e| e.to_string())?
            .raw()
            .next()
            .transpose()
            .map_err(|e| e.to_string())?;
        let applied = match current.as_deref() {
            Some([SqlStorageValue::Integer(v)]) => usize::try_from(*v).unwrap_or(0),
            _ => 0,
        };
        for (index, steps) in MIGRATIONS.iter().enumerate().skip(applied) {
            for step in *steps {
                self.run(step, vec![])?;
            }
            let version = i64::try_from(index + 1).map_err(|e| e.to_string())?;
            self.run(
                "INSERT INTO schema_migration (version) VALUES (?)",
                vec![version.into()],
            )?;
        }
        self.migrated.set(true);
        Ok(())
    }
}

impl TileStore for SqlTileStore {
    fn load(&self, coord: TileCoord) -> Result<Option<Vec<u8>>, String> {
        self.migrate()?;
        let row = self
            .sql
            .exec(
                "SELECT doc_state FROM tile WHERE level = ? AND tx = ? AND ty = ?",
                coord_bindings(coord),
            )
            .map_err(|e| e.to_string())?
            .raw()
            .next()
            .transpose()
            .map_err(|e| e.to_string())?;
        match row {
            None => Ok(None),
            Some(mut values) => match values.pop() {
                Some(SqlStorageValue::Blob(bytes)) => Ok(Some(bytes)),
                other => Err(format!(
                    "tile {coord:?} has a non-blob doc_state: {other:?}"
                )),
            },
        }
    }

    fn save(&self, record: &TileRecord) -> Result<(), String> {
        self.migrate()?;
        let updated_at = i64::try_from(record.updated_at).map_err(|e| e.to_string())?;
        let mut bindings = coord_bindings(record.coord);
        bindings.push(record.doc_state.clone().into());
        bindings.push(updated_at.into());
        self.run(
            "INSERT INTO tile (level, tx, ty, doc_state, updated_at) VALUES (?, ?, ?, ?, ?)
             ON CONFLICT (level, tx, ty)
             DO UPDATE SET doc_state = excluded.doc_state, updated_at = excluded.updated_at",
            bindings,
        )?;
        self.run(
            "DELETE FROM object_index WHERE level = ? AND tx = ? AND ty = ?",
            coord_bindings(record.coord),
        )?;
        for (object_id, bbox) in &record.objects {
            let mut bindings = coord_bindings(record.coord);
            bindings.push(object_id.as_str().into());
            bindings.push(bbox_json(bbox).into());
            self.run(
                "INSERT INTO object_index (level, tx, ty, object_id, bbox) VALUES (?, ?, ?, ?, ?)",
                bindings,
            )?;
        }
        Ok(())
    }
}

