import { Encoder } from "cbor-x";
import { z } from "zod";

export const frameKind = z.enum(["Subscribe", "Unsubscribe", "Sync", "Awareness", "Reject"]);

export const frame = z.strictObject({
  tileKey: z.string(),
  kind: frameKind,
  payload: z.instanceof(Uint8Array),
});

export type FrameKind = z.infer<typeof frameKind>;
export type Frame = z.infer<typeof frame>;

export const BOARD_KEY = "";

export type FrameResult = { ok: true; value: Frame } | { ok: false; error: string };

const cbor = new Encoder({
  useRecords: false,
  mapsAsObjects: true,
  variableMapSize: true,
  tagUint8Array: false,
});

export const encodeFrame = (value: Frame): Uint8Array =>
  cbor.encode({ tileKey: value.tileKey, kind: value.kind, payload: value.payload });

export const decodeFrame = (bytes: Uint8Array): FrameResult => {
  const parsed = frame.safeParse(cbor.decode(bytes));
  if (!parsed.success) {
    return { ok: false, error: parsed.error.message };
  }
  return { ok: true, value: parsed.data };
};
import { expect, test } from "vitest";
import { decodeFrame, encodeFrame, type Frame } from "./frame";

const sync: Frame = { tileKey: "-3:4:-5", kind: "Sync", payload: new Uint8Array([0, 1, 2]) };

const hex = (bytes: Uint8Array): string =>
  `${Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("")}\n`;

test("matches the golden frame fixture shared with the server", async () => {
  await expect(hex(encodeFrame(sync))).toMatchFileSnapshot("../fixtures/frame.cbor.hex");
});

test("round-trips a frame and rejects an unknown kind", () => {
  const decoded = decodeFrame(encodeFrame(sync));
  expect(decoded.ok && Array.from(decoded.value.payload)).toEqual([0, 1, 2]);
  const bogus = encodeFrame({ ...sync, kind: "Nope" as Frame["kind"] });
  expect(decodeFrame(bogus).ok).toBe(false);
});
